'use strict';

const fs = require('fs');
const input = fs.readFileSync(0);
let pos = 0;

function nextInt() {
  while (pos < input.length && input[pos] <= 32) pos++;
  let value = 0;
  while (pos < input.length && input[pos] >= 48 && input[pos] <= 57) {
    value = value * 10 + input[pos] - 48;
    pos++;
  }
  return value;
}

function nextChar() {
  while (pos < input.length && input[pos] <= 32) pos++;
  return String.fromCharCode(input[pos++]);
}

const N = nextInt();
const M = nextInt();
const P = nextInt();

const rows = new Int32Array(N);
const cols = new Int32Array(M);

for (let i = 0; i < N; i++) rows[i] = i;
for (let j = 0; j < M; j++) cols[j] = j;

for (let i = 0; i < P; i++) {
  const operation = nextChar();
  const a = nextInt() - 1;
  const b = nextInt() - 1;

  if (operation === 'L') {
    const temp = rows[a];
    rows[a] = rows[b];
    rows[b] = temp;
  } else {
    const temp = cols[a];
    cols[a] = cols[b];
    cols[b] = temp;
  }
}

let outputParts = [];
let outputLength = 0;

function flush() {
  if (outputParts.length > 0) {
    process.stdout.write(outputParts.join(''));
    outputParts = [];
    outputLength = 0;
  }
}

const batchSize = 10000;

for (let i = 0; i < N; i++) {
  let j = 0;

  while (j < M) {
    const end = Math.min(j + batchSize, M);
    const values = new Array(end - j);

    for (let k = j; k < end; k++) {
      values[k - j] = String(rows[i] * M + cols[k] + 1);
    }

    let part = values.join(' ');
    if (j > 0) part = ' ' + part;
    outputParts.push(part);
    outputLength += part.length;
    j = end;

    if (outputLength >= 65536) flush();
  }

  outputParts.push('\n');
  outputLength++;

  if (outputLength >= 65536) flush();
}

flush();
